const PLAN_DURATIONS = {
  Monthly: 30,
  Quarterly: 90,
  'Half-Yearly': 180,
  Yearly: 365,
};
const VALID_GENDERS = ['Male', 'Female', 'Other', 'Prefer not to say'];
const VALID_PAYMENT_STATUSES = ['Paid', 'Pending'];

const todayIST = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(new Date());

const submittedAtIST = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
}).format(new Date()) + ' IST';

function cleanStr(val) {
  if (val === undefined || val === null) return '';
  return String(val).trim();
}

function normalizeIndianMobile(raw) {
  const str = cleanStr(raw);
  if (!str) return { valid: false, normalized: '', reason: 'empty' };
  let digits = str.replace(/\D/g, '');
  if (digits.length === 12 && digits.startsWith('91')) {
    digits = digits.slice(2);
  } else if (digits.length === 11 && digits.startsWith('0')) {
    digits = digits.slice(1);
  }
  if (!/^[6-9]\d{9}$/.test(digits)) {
    return { valid: false, normalized: '', reason: 'format' };
  }
  return { valid: true, normalized: '91' + digits };
}

function parseIsoDate(raw) {
  const str = cleanStr(raw);
  if (!str) return null;
  const match = str.match(/^(\d{4})-(\d{2})-(\d{2})(?:$|T|\s)/);
  if (!match) return null;
  const y = Number(match[1]);
  const m = Number(match[2]);
  const d = Number(match[3]);
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (
    dt.getUTCFullYear() !== y ||
    dt.getUTCMonth() !== m - 1 ||
    dt.getUTCDate() !== d
  ) {
    return null;
  }
  return `${match[1]}-${match[2]}-${match[3]}`;
}

return $input.all().map((item) => {
  const raw = item.json || {};
  const errors = [];

  // Never trust user-supplied member_id, memberId, or id values.
  const fullName = cleanStr(raw['Full Name'] ?? raw.full_name ?? raw.name);
  if (!fullName) {
    errors.push('Full Name is required and cannot be empty.');
  }

  const rawPhone = raw['Phone Number'] ?? raw.phone ?? raw.phone_number;
  const phoneResult = normalizeIndianMobile(rawPhone);
  if (!phoneResult.valid) {
    errors.push(
      'Phone Number must be a valid Indian mobile number (10 digits starting with 6-9, optionally prefixed with +91, 91, or 0).'
    );
  }

  const email = cleanStr(raw['Email'] ?? raw.email).toLowerCase();
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    errors.push('Email must be a valid email address.');
  }

  const gender = cleanStr(raw['Gender'] ?? raw.gender);
  if (gender && !VALID_GENDERS.includes(gender)) {
    errors.push(`Gender must be one of: ${VALID_GENDERS.join(', ')}.`);
  }

  const rawDob = cleanStr(raw['Date of Birth'] ?? raw.date_of_birth ?? raw.dob);
  let dateOfBirth = '';
  if (rawDob) {
    const parsedDob = parseIsoDate(rawDob);
    if (!parsedDob) {
      errors.push('Date of Birth must be a valid calendar date in YYYY-MM-DD format.');
    } else if (parsedDob > todayIST) {
      errors.push('Date of Birth cannot be in the future.');
    } else {
      dateOfBirth = parsedDob;
    }
  }

  const address = cleanStr(raw['Address'] ?? raw.address);
  const emergencyContactName = cleanStr(
    raw['Emergency Contact Name'] ?? raw.emergency_contact_name
  );

  const rawEmergencyPhone = cleanStr(
    raw['Emergency Contact Phone'] ?? raw.emergency_contact_phone
  );
  let emergencyContactPhone = '';
  if (rawEmergencyPhone) {
    const ecPhoneResult = normalizeIndianMobile(rawEmergencyPhone);
    if (!ecPhoneResult.valid) {
      errors.push(
        'Emergency Contact Phone must be a valid Indian mobile number (or left blank).'
      );
    } else {
      emergencyContactPhone = ecPhoneResult.normalized;
    }
  }

  const plan = cleanStr(raw['Membership Plan'] ?? raw.plan ?? raw.membership_plan);
  if (!Object.prototype.hasOwnProperty.call(PLAN_DURATIONS, plan)) {
    errors.push(
      `Membership Plan must be one of: ${Object.keys(PLAN_DURATIONS).join(', ')}.`
    );
  }

  const rawFee = raw['Membership Fee'] ?? raw.fee ?? raw.membership_fee;
  const feeStr = cleanStr(rawFee);
  const feeNum = feeStr === '' ? NaN : Number(feeStr);
  if (!Number.isFinite(feeNum) || feeNum < 0) {
    errors.push('Membership Fee must be a valid non-negative number.');
  }

  const rawStartDate = raw['Start Date'] ?? raw.start_date;
  const startDate = parseIsoDate(rawStartDate);
  if (!startDate) {
    errors.push('Start Date must be a valid calendar date in YYYY-MM-DD format.');
  }

  const paymentStatus = cleanStr(
    raw['Payment Status'] ?? raw.payment_status
  );
  if (!VALID_PAYMENT_STATUSES.includes(paymentStatus)) {
    errors.push(
      `Payment Status must be one of: ${VALID_PAYMENT_STATUSES.join(', ')}.`
    );
  }

  const notes = cleanStr(raw['Notes'] ?? raw.notes);
  const isValid = errors.length === 0;

  return {
    json: {
      is_valid: isValid,
      validation_errors: errors,
      error_message: errors.map((e, idx) => `${idx + 1}. ${e}`).join('\n'),
      submitted_at_ist: submittedAtIST,
      validated_data: isValid
        ? {
            name: fullName,
            phone: phoneResult.normalized,
            email,
            gender,
            date_of_birth: dateOfBirth,
            address,
            emergency_contact_name: emergencyContactName,
            emergency_contact_phone: emergencyContactPhone,
            plan,
            duration_days: PLAN_DURATIONS[plan],
            fee: feeNum,
            start_date: startDate,
            payment_status: paymentStatus,
            notes,
          }
        : null,
    },
  };
});

const PLAN_DURATIONS = {
  Monthly: 30,
  Quarterly: 90,
  'Half-Yearly': 180,
  Yearly: 365,
};

const ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const generatedIds = new Set();

function generateUniqueMemberId() {
  let candidate = '';
  do {
    const timePart = Date.now()
      .toString(36)
      .toUpperCase()
      .slice(-4)
      .padStart(4, '0');
    let randPart = '';
    if (typeof globalThis.crypto !== 'undefined' && typeof globalThis.crypto.getRandomValues === 'function') {
      const bytes = new Uint8Array(4);
      globalThis.crypto.getRandomValues(bytes);
      for (let i = 0; i < 4; i++) {
        randPart += ALPHABET[bytes[i] % ALPHABET.length];
      }
    } else {
      for (let i = 0; i < 4; i++) {
        randPart += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];
      }
    }
    candidate = `MEM-${timePart}${randPart}`;
  } while (generatedIds.has(candidate));
  generatedIds.add(candidate);
  return candidate;
}

function addDays(isoDate, days) {
  const [y, m, d] = isoDate.split('-').map(Number);
  const utcMs = Date.UTC(y, m - 1, d) + days * 86400000;
  const dt = new Date(utcMs);
  const yy = dt.getUTCFullYear();
  const mm = String(dt.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(dt.getUTCDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

return $input.all().map((item) => {
  const v = item.json.validated_data;
  if (!v) {
    throw new Error('Missing validated_data in Generate Member Record.');
  }

  const durationDays = PLAN_DURATIONS[v.plan];
  if (!durationDays) {
    throw new Error(`Unsupported membership plan: ${v.plan}`);
  }

  const memberId = generateUniqueMemberId();
  const expiryDate = addDays(v.start_date, durationDays);
  const lastPaymentDate = v.payment_status === 'Paid' ? v.start_date : '';
  const onboardingNote = 'Onboarding: Day-1 Welcome | Next Follow-Up: +3d';

  return {
    json: {
      member_id: memberId,
      name: v.name,
      phone: v.phone,
      email: v.email,
      gender: v.gender,
      date_of_birth: v.date_of_birth,
      address: v.address,
      emergency_contact_name: v.emergency_contact_name,
      emergency_contact_phone: v.emergency_contact_phone,
      plan: v.plan,
      fee: v.fee,
      start_date: v.start_date,
      expiry_date: expiryDate,
      payment_status: v.payment_status,
      last_payment_date: lastPaymentDate,
      last_reminder_date: '',
      member_status: 'Active',
      notes: v.notes ? `${v.notes} | ${onboardingNote}` : onboardingNote,
    },
  };
});

